import Image from "next/image";

// Brand logo built from the approved artwork (Option 1 + Favicon 1).
// Assets are generated by scripts/brand-assets.mjs into /public/brand.

/** Compact horizontal lockup: favicon emblem + "EcoSoul / Uttarakhand Travel" wordmark. */
export function Logo({ light = false, size = "md" }: { light?: boolean; size?: "sm" | "md" }) {
  const h = size === "sm" ? 34 : 42;
  return (
    <span className="flex items-center gap-2.5">
      <Image src="/brand/emblem.png" alt="" width={h} height={h} priority className="rounded-[22%] shadow-sm ring-1 ring-black/5" />
      <Image
        src={light ? "/brand/wordmark-light.png" : "/brand/wordmark.png"}
        alt="EcoSoul Uttarakhand Travel"
        width={Math.round(h * 0.95 * (495 / 152))}
        height={Math.round(h * 0.95)}
        priority
      />
    </span>
  );
}

/** Full illustrated logo (Option 1) — use on light backgrounds only. */
export function FullLogo({ width = 260, className = "", priority = false }: { width?: number; className?: string; priority?: boolean }) {
  return (
    <Image
      src="/brand/logo-full.png"
      alt="EcoSoul Uttarakhand Travel — Devbhoomi, Uttarakhand"
      width={width}
      height={Math.round(width * (478 / 588))}
      priority={priority}
      className={className}
    />
  );
}
